import { LinkButton } from "@/components/ui/button"
import { SemanticContent } from "@/components/ui/semantic-content"

/**
 * tailark mist call-to-action-1 rebuilt for aria: Button asChild + next/link
 * replaced by the aria-nova LinkButton (React Aria Link with button styles).
 */
export default function CallToAction({
  heading = "Build your next page in minutes",
  description,
  actions = [
    { label: "Get started", href: "#" },
    { label: "Book a demo", href: "#", variant: "outline" as const },
  ],
}: {
  heading?: string
  description?: string
  actions?: { label: string; href: string; variant?: "default" | "outline" }[]
}) {
  return (
    <section data-slot="call-to-action">
      <div className="py-12">
        <div className="mx-auto max-w-5xl px-6">
          <div className="space-y-6 text-center">
            <SemanticContent as="h2" className="text-foreground lg:text-4xl">{heading}</SemanticContent>
            {description && <SemanticContent as="p" className="mx-auto max-w-xl text-muted-foreground">{description}</SemanticContent>}
            <div className="flex justify-center gap-3">
              {actions.slice(0, 2).map((a) => (
                <LinkButton key={a.label} href={a.href} size="lg" variant={a.variant ?? "default"}>
                  {a.label}
                </LinkButton>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}
